// Entradas: Supabase (leads) e Sheets (blacklist)
const leads = items;
const blacklist = $items('Buscar lista de opt-outs', 0, 0);

// --- Função robusta para normalizar telefone ---
function normalizePhone(phone) {
  if (!phone) return '';

  let clean = String(phone).replace(/\D/g, ''); // remove tudo que não é número

  // Remove prefixo internacional 55 se existir
  if (clean.startsWith('55')) clean = clean.slice(2);

  // Se tiver mais de 11 dígitos (erro comum em planilhas), pega só os últimos 11
  if (clean.length > 11) clean = clean.slice(-11);

  // Se tiver menos de 11 e mais de 8 (fixo sem DDD), ignora
  if (clean.length < 10) return '';

  // Corrige se for 10 dígitos (sem o 9)
  if (clean.length === 10) {
    clean = clean.slice(0, 2) + '9' + clean.slice(2);
  }

  return clean;
}

// --- Cria lista de bloqueados normalizados ---
const blacklistPhones = blacklist
  .map(b => normalizePhone(b.json.Telefone || b.json.telefone))
  .filter(Boolean);

// --- Filtra os leads que NÃO estão na blacklist ---
const filteredLeads = leads.filter(l => {
  const leadPhone = normalizePhone(l.json.telefone);
  const isBlocked = blacklistPhones.includes(leadPhone);
  return leadPhone && !isBlocked;
});

// --- Logs úteis para debug ---
console.log('Blacklisted phones:', blacklistPhones);
console.log('Total leads recebidos:', leads.length);
console.log('Leads após filtro:', filteredLeads.length);

return filteredLeads;

// Code node — Run Once for All Items
// NÃO baixa mídia por lead. Meta (Cloud API) envia imagem por URL -> base64 não é usado.
// Só a branch Evolution ("Diogo IA") consome base64 -> baixa a imagem UMA vez, com timeout.

function normalizeTelefone(raw) {
  if (raw == null) return "";
  let d = String(raw).replace(/\D/g, "").replace(/^0+/, "");
  if (!d) return "";
  if (d.startsWith("55")) d = d.slice(2);
  if (d.length === 10) {
    const primeiro = d.slice(2)[0];
    if (["6","7","8","9"].includes(primeiro)) d = d.slice(0,2) + "9" + d.slice(2);
  }
  return "55" + d;
}
function safeParam(val) {
  if (val == null) return " ";
  if (Array.isArray(val)) { const v = val[0]; return (v == null) ? " " : String(v).trim(); }
  return String(val).trim() || " ";
}
function stripBOM(buf){ return (buf.length>=3 && buf[0]===0xEF && buf[1]===0xBB && buf[2]===0xBF) ? buf.slice(3) : buf; }
function fixPngSignature(buf){
  if (buf.length>=7 && buf[0]===0x50 && buf[1]===0x4E && buf[2]===0x47 && buf[3]===0x0D && buf[4]===0x0A && buf[5]===0x1A && buf[6]===0x0A){
    return Buffer.concat([Buffer.from([0x89]), buf]);
  }
  return buf;
}

// ---- Baixa a imagem do disparo UMA única vez (só quando a branch precisa de base64) ----
const first = items[0]?.json || {};
const origem = String(first.origem || "").trim();
const tipoMidia = String(first.tipo_midia || "").toLowerCase().trim();
const sharedUrl = String(first.imagem || "").trim();

// Branches que consomem base64 (Evolution API). As demais (Meta) usam imagem_url.
const BASE64_ORIGENS = ["Diogo IA"];
const precisaBase64 = BASE64_ORIGENS.includes(origem) && !!sharedUrl;

let base64 = "";
let mime = "";

if (precisaBase64) {
  try {
    const res = await this.helpers.httpRequest({
      method: "GET",
      url: sharedUrl,
      headers: { "User-Agent": "Mozilla/5.0" },
      responseFormat: "arraybuffer",
      returnFullResponse: true,
      timeout: 20000, // segurança: nunca trava o disparo inteiro
    });
    let buf = Buffer.from(res.data ?? res.body ?? res);
    mime = (res.headers?.["content-type"] || "").split(";")[0].trim();
    buf = stripBOM(buf);
    const isPng = mime.includes("png") || (buf.length>=3 && buf[0]===0x50 && buf[1]===0x4E && buf[2]===0x47);
    if (tipoMidia === "imagem" && isPng && buf.length>=7) buf = fixPngSignature(buf);
    base64 = buf.toString("base64");
  } catch (e) {
    base64 = "";
  }
}

// ---- Monta o corpo de cada lead (sem nenhum I/O por item) ----
return items.map((item) => {
  const j = item.json || {};
  return {
    json: {
      mensagem: j.mensagem,
      remetente: j.remetente,
      nome: j.nome,
      telefone: normalizeTelefone(j.telefone),
      tipo_midia: String(j.tipo_midia ?? "").toLowerCase().trim(),
      mime,
      base64,
      imagem_url: j.imagem_url,
      template_name: j.template_name ?? "",
      param_1: safeParam(j.param_1),
      param_2: safeParam(j.param_2),
      param_3: safeParam(j.param_3),
      param_4: safeParam(j.param_4),
      param_5: safeParam(j.param_5),
      mensagem_completa: j.mensagem_completa ?? "",
      origem: j.origem,
    },
  };
});

